package com.ultimatebank;

import com.google.inject.Provides;
import com.ultimatebank.core.BankFeature;
import com.ultimatebank.core.FeatureManager;
import com.ultimatebank.core.snapshots.StorageSnapshots;
import com.ultimatebank.feature.storagesavings.StorageSavingsFeature;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;

@Slf4j
// Needed to inject core bank tag services (BankTagsService, TagManager)
@PluginDependency(BankTagsPlugin.class)
@PluginDescriptor(
	name = "Ultimate Bank",
	description = "Bank toolkit: see what could be stored outside your bank and which storage upgrades free the most space",
	tags = {"bank", "storage", "poh", "costume", "space", "stash", "tackle box", "seed vault", "wasted"}
)
public class UltimateBankPlugin extends Plugin
{
	/**
	 * Every feature in the plugin. Add new features here (order = start order).
	 */
	private static final List<Class<? extends BankFeature>> FEATURES = List.of(
		StorageSavingsFeature.class
	);

	@Inject
	private ClientThread clientThread;

	@Inject
	private FeatureManager featureManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private StorageSnapshots storageSnapshots;

	@Override
	protected void startUp()
	{
		// Shared services run whatever features are on
		eventBus.register(storageSnapshots);
		clientThread.invokeLater(storageSnapshots::load);

		featureManager.load(FEATURES);
		log.debug("Loaded {} features", FEATURES.size());
		clientThread.invokeLater(featureManager::sync);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(featureManager::stopAll);
		eventBus.unregister(storageSnapshots);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (UltimateBankConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(featureManager::sync);
		}
	}

	@Provides
	UltimateBankConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UltimateBankConfig.class);
	}
}

package com.ultimatebank.core;

import com.ultimatebank.UltimateBankConfig;

/**
 * A self-contained feature of the plugin (e.g. bank value, tag layouts).
 * <p>
 * While enabled, the feature instance is registered on the EventBus, so it may declare
 * {@code @Subscribe} methods directly. Features are Guice singletons created by the plugin's
 * injector, so they may {@code @Inject} anything the plugin can.
 * <p>
 * To add a feature, follow .claude/skills/new-feature/SKILL.md.
 */
public interface BankFeature
{
	/**
	 * Whether the user has this feature switched on. Usually reads a single toggle from config.
	 */
	boolean isEnabled(UltimateBankConfig config);

	/**
	 * Called on the client thread after the feature is registered on the EventBus.
	 * Add overlays, build caches, etc. here.
	 */
	default void startUp()
	{
	}

	/**
	 * Called on the client thread before the feature is unregistered from the EventBus.
	 * Must undo everything startUp() did (remove overlays, restore widgets, clear caches).
	 */
	default void shutDown()
	{
	}
}

package com.ultimatebank.core;

import com.google.inject.Injector;
import com.ultimatebank.UltimateBankConfig;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;

/**
 * Starts and stops {@link BankFeature}s so that exactly the enabled ones are running.
 * All methods must be called on the client thread.
 */
@Slf4j
@Singleton
public class FeatureManager
{
	private final Injector injector;
	private final EventBus eventBus;
	private final UltimateBankConfig config;

	private final List<BankFeature> features = new ArrayList<>();
	private final Set<BankFeature> running = new LinkedHashSet<>();

	@Inject
	FeatureManager(Injector injector, EventBus eventBus, UltimateBankConfig config)
	{
		this.injector = injector;
		this.eventBus = eventBus;
		this.config = config;
	}

	public void load(List<Class<? extends BankFeature>> featureClasses)
	{
		features.clear();
		for (Class<? extends BankFeature> featureClass : featureClasses)
		{
			features.add(injector.getInstance(featureClass));
		}
	}

	/**
	 * Starts newly enabled features and stops newly disabled ones.
	 */
	public void sync()
	{
		log.debug("Syncing {} features ({} running)", features.size(), running.size());
		for (BankFeature feature : features)
		{
			boolean enabled = feature.isEnabled(config);
			if (enabled && !running.contains(feature))
			{
				start(feature);
			}
			else if (!enabled && running.contains(feature))
			{
				stop(feature);
			}
		}
	}

	public void stopAll()
	{
		for (BankFeature feature : new ArrayList<>(running))
		{
			stop(feature);
		}
	}

	private void start(BankFeature feature)
	{
		log.debug("Starting feature {}", feature.getClass().getSimpleName());
		eventBus.register(feature);
		running.add(feature);
		try
		{
			feature.startUp();
		}
		catch (Exception e)
		{
			log.warn("Feature {} failed to start", feature.getClass().getSimpleName(), e);
			stop(feature);
		}
	}

	private void stop(BankFeature feature)
	{
		log.debug("Stopping feature {}", feature.getClass().getSimpleName());
		try
		{
			feature.shutDown();
		}
		catch (Exception e)
		{
			log.warn("Feature {} failed to shut down cleanly", feature.getClass().getSimpleName(), e);
		}
		eventBus.unregister(feature);
		running.remove(feature);
	}
}

package com.ultimatebank.core;

import com.ultimatebank.UltimateBankPlugin;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.MenuAction;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;

/**
 * Opens the plugin's settings in the RuneLite configuration panel, e.g. from a feature's sidebar panel.
 * There's no direct API for this; the core Configuration plugin opens a plugin's settings when one of its overlays'
 * "Configure" menu entries is clicked, so we post that event for an overlay belonging to our plugin.
 */
@Singleton
public class SettingsOpener
{
	private static final OverlayMenuEntry CONFIGURE = new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "Ultimate Bank");

	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final Overlay owner;

	@Inject
	SettingsOpener(ClientThread clientThread, EventBus eventBus, UltimateBankPlugin plugin)
	{
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		// Never added to the overlay manager; it only tells the Configuration plugin whose settings to open
		this.owner = new Overlay(plugin)
		{
			@Override
			public Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
	}

	/**
	 * Opens Ultimate Bank's settings. Safe to call from any thread.
	 */
	public void open()
	{
		// Overlay menu clicks are normally posted on the client thread
		clientThread.invokeLater(() -> eventBus.post(new OverlayMenuClicked(CONFIGURE, owner)));
	}
}

