package com.ultimatebank.core.snapshots;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Reads a player-owned house costume room storage interface: which storage it is (from its text) and which items
 * are stored in it. Adapted from Where's My Stuff by Wozak-1. Must be called on the client thread.
 */
@Singleton
class PohStorageScanner
{
	@Value
	static class Result
	{
		SnapshotLocation location;
		Map<Integer, Integer> quantities;
		/** Text of the interface's tier label, if any (logged to work out tier detection) */
		String tierText;
	}

	private final Client client;

	@Inject
	PohStorageScanner(Client client)
	{
		this.client = client;
	}

	/**
	 * @return what the open costume room interface holds, or null if none is open or it isn't populated yet
	 */
	Result scan()
	{
		Widget universe = client.getWidget(InterfaceID.PohCostumes.UNIVERSE);
		Widget items = client.getWidget(InterfaceID.PohCostumes.ITEMS);
		if (universe == null || items == null)
		{
			return null;
		}

		StringBuilder text = new StringBuilder();
		for (Widget widget : traverse(universe))
		{
			append(text, widget.getText());
			append(text, widget.getName());
		}
		SnapshotLocation location = SnapshotLocation.fromInterfaceText(text.toString());
		if (location == null)
		{
			return null;
		}

		Map<Integer, Integer> quantities = new HashMap<>();
		for (Widget widget : traverse(items))
		{
			// Stored items are drawn opaque; ones you could store but haven't are faded
			if (widget.isHidden() || widget.getItemId() <= 0 || widget.getOpacity() > 0)
			{
				continue;
			}
			quantities.put(widget.getItemId(), Math.max(1, widget.getItemQuantity()));
		}

		Widget tier = client.getWidget(InterfaceID.PohCostumes.TIER);
		return new Result(location, quantities, tier == null ? null : Text.removeTags(tier.getText()));
	}

	private static void append(StringBuilder text, String value)
	{
		if (value != null && !value.isEmpty())
		{
			text.append(' ').append(Text.removeTags(value));
		}
	}

	private static Iterable<Widget> traverse(Widget root)
	{
		Deque<Widget> queue = new ArrayDeque<>();
		Set<Widget> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		List<Widget> out = new ArrayList<>();
		queue.add(root);
		seen.add(root);
		while (!queue.isEmpty())
		{
			Widget widget = queue.removeFirst();
			out.add(widget);
			for (Widget[] children : new Widget[][]{widget.getChildren(), widget.getDynamicChildren(),
				widget.getStaticChildren(), widget.getNestedChildren()})
			{
				if (children == null)
				{
					continue;
				}
				for (Widget child : children)
				{
					if (child != null && seen.add(child))
					{
						queue.addLast(child);
					}
				}
			}
		}
		return out;
	}
}

package com.ultimatebank.core.snapshots;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * Item quantities in one location at one moment. Stored as JSON, so fields stay simple.
 */
@Getter
@EqualsAndHashCode
public final class Snapshot
{
	/** Quantity by item ID, as the game reports them (placeholders excluded) */
	private final Map<Integer, Integer> quantities;
	/** When it was taken, epoch millis */
	private final long takenAt;

	public Snapshot(Map<Integer, Integer> quantities, long takenAt)
	{
		this.quantities = Collections.unmodifiableMap(new HashMap<>(quantities));
		this.takenAt = takenAt;
	}

	/**
	 * @return e.g. "5 minutes ago", "3 hours ago", "2 days ago"
	 */
	public static String ago(long epochMillis)
	{
		long minutes = Math.max(0, (System.currentTimeMillis() - epochMillis) / 60_000);
		if (minutes < 60)
		{
			return minutes + (minutes == 1 ? " minute ago" : " minutes ago");
		}
		long hours = minutes / 60;
		if (hours < 48)
		{
			return hours + (hours == 1 ? " hour ago" : " hours ago");
		}
		return hours / 24 + " days ago";
	}

	public boolean sameContents(Snapshot other)
	{
		return other != null && quantities.equals(other.quantities);
	}
}

package com.ultimatebank.core.snapshots;

import java.util.List;

/**
 * Updates a location's snapshot history (oldest first) so it holds one entry per visit.
 */
final class SnapshotHistory
{
	private SnapshotHistory()
	{
	}

	/**
	 * Records a snapshot taken during a visit.
	 *
	 * @param replaceLast the last entry was appended earlier in this same visit, so this snapshot replaces it
	 * @return whether the history's last entry now belongs to this visit (pass it as replaceLast next time)
	 */
	static boolean record(List<Snapshot> history, Snapshot snapshot, boolean replaceLast, int max)
	{
		if (replaceLast && !history.isEmpty())
		{
			history.remove(history.size() - 1);
		}

		boolean appended;
		if (!history.isEmpty() && history.get(history.size() - 1).sameContents(snapshot))
		{
			// Unchanged since the last visit: just note it was seen now
			history.set(history.size() - 1, snapshot);
			appended = false;
		}
		else
		{
			history.add(snapshot);
			appended = true;
		}
		while (history.size() > max)
		{
			history.remove(0);
		}
		return appended;
	}
}

package com.ultimatebank.core.snapshots;

import java.util.Locale;
import lombok.Getter;

/**
 * Places whose contents are snapshotted: the bank and each player-owned house costume room storage.
 */
@Getter
public enum SnapshotLocation
{
	BANK("Bank", false),
	MAGIC_WARDROBE("POH magic wardrobe", true),
	TOY_BOX("POH toy box", true),
	CAPE_RACK("POH cape rack", true),
	TREASURE_CHEST("POH treasure chest", true),
	ARMOUR_CASE("POH armour case", true),
	FANCY_DRESS_BOX("POH fancy dress box", true),
	BOOKCASE("POH bookcase", true);

	private final String displayName;
	private final boolean poh;

	SnapshotLocation(String displayName, boolean poh)
	{
		this.displayName = displayName;
		this.poh = poh;
	}

	/**
	 * Works out which POH storage an interface is showing from its text, e.g. a "Toy box" title.
	 * From Where's My Stuff by Wozak-1.
	 *
	 * @return the storage, or null if the text names none
	 */
	public static SnapshotLocation fromInterfaceText(String text)
	{
		if (text == null)
		{
			return null;
		}
		String t = text.toLowerCase(Locale.ROOT);
		if (t.contains("magic wardrobe"))
		{
			return MAGIC_WARDROBE;
		}
		if (t.contains("toy box"))
		{
			return TOY_BOX;
		}
		if (t.contains("cape rack"))
		{
			return CAPE_RACK;
		}
		if (t.contains("treasure chest"))
		{
			return TREASURE_CHEST;
		}
		if (t.contains("armour case") || t.contains("armor case"))
		{
			return ARMOUR_CASE;
		}
		if (t.contains("fancy dress box") || t.contains("costume box"))
		{
			return FANCY_DRESS_BOX;
		}
		if (t.contains("bookcase") || t.contains("bookshelf"))
		{
			return BOOKCASE;
		}
		return null;
	}
}

package com.ultimatebank.core.snapshots;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.ultimatebank.UltimateBankConfig;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

/**
 * Remembers what's in the bank and each POH costume room storage, per account, so features can work before (or
 * without) the player opening them again. Keeps the last few snapshots of each location for "recently changed",
 * one per visit: while a location stays open its latest snapshot is updated in place, so the previous snapshot shows
 * everything taken or deposited during the visit.
 * Always on: registered on the EventBus by the plugin itself. All methods must be called on the client thread.
 */
@Slf4j
@Singleton
public class StorageSnapshots
{
	private static final String KEY_PREFIX = "snapshots.";
	/** The costume room interface fills in its items a couple of ticks after it opens */
	private static final int POH_SCAN_DELAY_TICKS = 2;
	private static final int POH_SCAN_ATTEMPTS = 6;
	/** Snapshots kept per location (the latest, plus a few earlier for comparisons) */
	private static final int HISTORY_SIZE = 5;

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final PohStorageScanner pohScanner;

	/** Oldest first */
	private final Map<SnapshotLocation, List<Snapshot>> histories = new EnumMap<>(SnapshotLocation.class);
	private final List<Consumer<SnapshotLocation>> listeners = new CopyOnWriteArrayList<>();
	/** Locations whose latest snapshot was appended during the current visit, so further changes replace it */
	private final Set<SnapshotLocation> visitEntries = EnumSet.noneOf(SnapshotLocation.class);
	private String loadedProfile;
	private boolean bankScanPending;
	/** The bank has been read since it was opened */
	private boolean bankVisit;
	/** The POH storage currently open, once read */
	private SnapshotLocation pohVisit;
	private int pohScanDelay = -1;
	private int pohScanAttemptsLeft;

	@Inject
	StorageSnapshots(Client client, ConfigManager configManager, Gson gson, PohStorageScanner pohScanner)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
		this.pohScanner = pohScanner;
	}

	/**
	 * @return the most recent snapshot of a location, or null if it's never been seen on this account
	 */
	public Snapshot latest(SnapshotLocation location)
	{
		List<Snapshot> history = histories.get(location);
		return history == null || history.isEmpty() ? null : history.get(history.size() - 1);
	}

	/**
	 * @return the snapshot before the latest one with different contents, or null
	 */
	public Snapshot previous(SnapshotLocation location)
	{
		List<Snapshot> history = histories.get(location);
		return history == null || history.size() < 2 ? null : history.get(history.size() - 2);
	}

	/**
	 * Called with the location whenever a snapshot is recorded, or with null when the account's snapshots are
	 * (re)loaded. Remove on shutdown.
	 */
	public void addListener(Consumer<SnapshotLocation> listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Consumer<SnapshotLocation> listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Loads the current account's snapshots, if a different account's (or none) are loaded.
	 */
	public void load()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null || profile.equals(loadedProfile))
		{
			return;
		}
		loadedProfile = profile;
		histories.clear();
		endVisits();
		for (SnapshotLocation location : SnapshotLocation.values())
		{
			String json = configManager.getRSProfileConfiguration(UltimateBankConfig.GROUP, key(location));
			if (json == null || json.isEmpty())
			{
				continue;
			}
			try
			{
				List<Snapshot> history = gson.fromJson(json, new TypeToken<List<Snapshot>>()
				{
				}.getType());
				if (history != null && !history.isEmpty())
				{
					histories.put(location, new ArrayList<>(history));
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Ignoring unreadable {} snapshot", location, e);
			}
		}
		log.debug("Loaded snapshots for {} locations", histories.size());
		notifyListeners(null);
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		load();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			load();
		}
		else
		{
			endVisits();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			// Read it next tick, once the bank has finished updating
			bankScanPending = true;
		}
		else if (event.getContainerId() == InventoryID.INV && client.getWidget(InterfaceID.PohCostumes.UNIVERSE) != null)
		{
			// Taking something out of (or putting it into) POH storage changes the inventory; the storage interface
			// fires nothing of its own, so read it again next tick
			pohScanDelay = 1;
			pohScanAttemptsLeft = POH_SCAN_ATTEMPTS;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.POH_COSTUMES)
		{
			pohScanDelay = POH_SCAN_DELAY_TICKS;
			pohScanAttemptsLeft = POH_SCAN_ATTEMPTS;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (bankScanPending)
		{
			bankScanPending = false;
			scanBank();
		}

		if (pohScanDelay > 0)
		{
			pohScanDelay--;
		}
		else if (pohScanDelay == 0)
		{
			scanPoh();
		}

		if (bankVisit && client.getWidget(InterfaceID.Bankmain.ITEMS) == null)
		{
			bankVisit = false;
			visitEntries.remove(SnapshotLocation.BANK);
		}
		if (pohVisit != null && client.getWidget(InterfaceID.PohCostumes.UNIVERSE) == null)
		{
			visitEntries.remove(pohVisit);
			pohVisit = null;
		}
	}

	private void endVisits()
	{
		visitEntries.clear();
		bankVisit = false;
		pohVisit = null;
	}

	private void scanBank()
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		// Only trust the container while the bank is open (or it changed just as it closed)
		if (bank == null || !bankVisit && client.getWidget(InterfaceID.Bankmain.ITEMS) == null)
		{
			return;
		}
		bankVisit = true;

		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : bank.getItems())
		{
			// Placeholders have quantity 0
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		record(SnapshotLocation.BANK, quantities);
	}

	private void scanPoh()
	{
		PohStorageScanner.Result result = pohScanner.scan();
		if (result != null)
		{
			pohScanDelay = -1;
			if (pohVisit != null && pohVisit != result.getLocation())
			{
				visitEntries.remove(pohVisit);
			}
			pohVisit = result.getLocation();
			log.debug("Scanned {}: {} items stored, tier text '{}'", result.getLocation(), result.getQuantities().size(),
				result.getTierText());
			record(result.getLocation(), result.getQuantities());
		}
		else if (--pohScanAttemptsLeft > 0)
		{
			pohScanDelay = 1;
		}
		else
		{
			pohScanDelay = -1;
			log.debug("Couldn't recognise the POH storage interface");
		}
	}

	private void record(SnapshotLocation location, Map<Integer, Integer> quantities)
	{
		load();
		if (loadedProfile == null)
		{
			return;
		}

		Snapshot snapshot = new Snapshot(quantities, System.currentTimeMillis());
		List<Snapshot> history = histories.computeIfAbsent(location, k -> new ArrayList<>());
		if (SnapshotHistory.record(history, snapshot, visitEntries.contains(location), HISTORY_SIZE))
		{
			visitEntries.add(location);
		}
		else
		{
			visitEntries.remove(location);
		}

		configManager.setRSProfileConfiguration(UltimateBankConfig.GROUP, key(location), gson.toJson(history));
		notifyListeners(location);
	}

	/**
	 * @return every location's latest snapshot
	 */
	public Map<SnapshotLocation, Snapshot> latestAll()
	{
		Map<SnapshotLocation, Snapshot> latest = new EnumMap<>(SnapshotLocation.class);
		for (SnapshotLocation location : histories.keySet())
		{
			latest.put(location, latest(location));
		}
		return Collections.unmodifiableMap(latest);
	}

	private static String key(SnapshotLocation location)
	{
		return KEY_PREFIX + location.name().toLowerCase(Locale.ROOT);
	}

	private void notifyListeners(SnapshotLocation location)
	{
		listeners.forEach(listener -> listener.accept(location));
	}
}

package com.ultimatebank.feature.storagesavings;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.client.util.Text;

/**
 * Resolves the user's ignore list (comma-separated item names, item IDs or {@code *} wildcards) into item IDs.
 * Names match ignoring case and whitespace, and a name shared by several items ignores all of them.
 */
final class IgnoreList
{
	private IgnoreList()
	{
	}

	/**
	 * @param namesToIds item IDs by {@link #normalize normalized} name, for every item that can be flagged
	 */
	static Set<Integer> resolve(String csv, Map<String, Set<Integer>> namesToIds)
	{
		if (csv == null || csv.isBlank())
		{
			return Collections.emptySet();
		}

		Set<Integer> ids = new HashSet<>();
		for (String entry : Text.fromCSV(csv))
		{
			String name = normalize(entry);
			if (name.isEmpty())
			{
				continue;
			}

			if (name.chars().allMatch(Character::isDigit))
			{
				try
				{
					ids.add(Integer.parseInt(name));
				}
				catch (NumberFormatException e)
				{
					// too long to be an item ID
				}
			}
			else if (name.indexOf('*') >= 0)
			{
				Pattern pattern = wildcard(name);
				namesToIds.forEach((itemName, itemIds) ->
				{
					if (pattern.matcher(itemName).matches())
					{
						ids.addAll(itemIds);
					}
				});
			}
			else
			{
				ids.addAll(namesToIds.getOrDefault(name, Collections.emptySet()));
			}
		}
		return ids;
	}

	/**
	 * @return whether the list has an entry naming exactly this item (by name or ID), i.e. one that
	 * {@link #remove} would take out
	 */
	static boolean containsExact(String csv, String itemName, int itemId)
	{
		String name = normalize(itemName);
		String id = String.valueOf(itemId);
		return Text.fromCSV(csv == null ? "" : csv).stream()
			.map(IgnoreList::normalize)
			.anyMatch(entry -> entry.equals(name) || entry.equals(id));
	}

	static String add(String csv, String itemName)
	{
		Collection<String> entries = new ArrayList<>(Text.fromCSV(csv == null ? "" : csv));
		entries.add(itemName);
		return Text.toCSV(entries);
	}

	/**
	 * Removes entries naming exactly this item. Wildcards that match it are left alone.
	 */
	static String remove(String csv, String itemName, int itemId)
	{
		String name = normalize(itemName);
		String id = String.valueOf(itemId);
		Collection<String> entries = new ArrayList<>(Text.fromCSV(csv == null ? "" : csv));
		entries.removeIf(entry ->
		{
			String normalized = normalize(entry);
			return normalized.equals(name) || normalized.equals(id);
		});
		return Text.toCSV(entries);
	}

	static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("\\s+", "");
	}

	private static Pattern wildcard(String normalized)
	{
		return Pattern.compile(Arrays.stream(normalized.split("\\*", -1))
			.map(Pattern::quote)
			.collect(Collectors.joining(".*")));
	}
}

package com.ultimatebank.feature.storagesavings;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Lays out the storable tab: one group per container, each starting on a new row with a blank title row above it
 * (the title itself is drawn by {@link StorableTitlesOverlay}). An item that fits several containers appears in each
 * group. Pure: no client access.
 */
final class StorableLayout
{
	static final int ROW = 8;
	private static final int EMPTY = -1;

	private StorableLayout()
	{
	}

	@Value
	static class Group
	{
		String title;
		List<Integer> itemIds;
	}

	@Value
	static class Result
	{
		/** Item ID by bank position, -1 for empty */
		int[] positions;
		/** Title by the (blank) row it's drawn on */
		Map<Integer, String> titleRows;
	}

	static Result build(List<Group> groups)
	{
		List<Integer> positions = new ArrayList<>();
		Map<Integer, String> titles = new LinkedHashMap<>();
		for (Group group : groups)
		{
			if (group.getItemIds().isEmpty())
			{
				continue;
			}
			padToRow(positions);
			titles.put(positions.size() / ROW, group.getTitle());
			for (int i = 0; i < ROW; i++)
			{
				positions.add(EMPTY);
			}
			positions.addAll(group.getItemIds());
		}
		return new Result(positions.stream().mapToInt(Integer::intValue).toArray(), Collections.unmodifiableMap(titles));
	}

	private static void padToRow(List<Integer> positions)
	{
		while (positions.size() % ROW != 0)
		{
			positions.add(EMPTY);
		}
	}
}

package com.ultimatebank.feature.storagesavings;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws each container's name and a divider line in the blank title rows of the grouped storable tab. Layouts can't
 * hold text, so titles are an overlay (approach from Bank Skill Sorting by Frailrain).
 */
@Singleton
class StorableTitlesOverlay extends Overlay
{
	private static final int ROW_HEIGHT = BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final Color SHADOW = new Color(0, 0, 0, 170);
	private static final Color TITLE = new Color(255, 255, 255, 230);
	private static final Color LINE = new Color(160, 160, 160, 170);

	private final Client client;
	private final StorageSavingsTagTab tagTab;

	@Inject
	StorableTitlesOverlay(Client client, StorageSavingsTagTab tagTab)
	{
		this.client = client;
		this.tagTab = tagTab;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<Integer, String> titles = tagTab.getTitleRows();
		if (titles.isEmpty())
		{
			return null;
		}

		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return null;
		}

		Rectangle clip = container.getBounds();
		Point origin = container.getCanvasLocation();
		int left = origin.getX() + BankTagsPlugin.BANK_ITEM_START_X;
		int right = clip.x + clip.width - 12;
		graphics.setFont(FontManager.getRunescapeBoldFont());

		for (Map.Entry<Integer, String> entry : titles.entrySet())
		{
			int rowTop = origin.getY() + BankTagsPlugin.BANK_ITEM_START_Y + entry.getKey() * ROW_HEIGHT - container.getScrollY();
			int lineY = rowTop + ROW_HEIGHT / 2;
			// Skip rows scrolled out of the bank's visible area
			if (lineY < clip.y + 6 || lineY > clip.y + clip.height - 4)
			{
				continue;
			}

			String title = entry.getValue();
			int baseline = lineY + graphics.getFontMetrics().getAscent() / 2 - 1;
			graphics.setColor(SHADOW);
			graphics.drawString(title, left + 1, baseline + 1);
			graphics.setColor(TITLE);
			graphics.drawString(title, left, baseline);

			int lineStart = left + graphics.getFontMetrics().stringWidth(title) + 8;
			if (right > lineStart)
			{
				graphics.setColor(LINE);
				graphics.drawLine(lineStart, lineY, right, lineY);
			}
		}
		return null;
	}
}

